  updateValidity(...rest: any[]): any {
    if (ngModelCtrl.$viewValue) {
        var value: any = ngModelCtrl.$viewValue;
        var dataValid: any = (value !== undefined) && value != null;
        ngModelCtrl.control?.setErrors(dataValid ? null : { deviceData: true });
        if (dataValid) {
            if (this.optDataKeys()) {
                ngModelCtrl.control?.setErrors(null);
            } else {
                var datasourceKeysValid: any = (value.dataKeys !== undefined) &&
                    value.dataKeys != null &&
                    value.dataKeys.length > 0;
                ngModelCtrl.control?.setErrors(datasourceKeysValid ? null : { datasourceKeys: true });
            }
        }
    }
  }
